set -euo pipefail
task_root=/opt/market-mcp-deploy/mcp
test "$(realpath "$task_root")" = "$task_root"
python3 - <<'PY'
import ast,base64,hashlib,shutil,zlib
from pathlib import Path
from datetime import datetime,timezone
root=Path('/opt/market-mcp-deploy/mcp')
target=root/'market_data/new_car_server.py'
assert target.resolve().parent==root/'market_data'
assert hashlib.sha256(target.read_bytes()).hexdigest()=='47af567c1c5b5b2deef9b4411e49e25e7053c9f5f9f2a18f0f093f7df62402d5','Remote source changed; stop'
payload=zlib.decompress(base64.b64decode(""))
ast.parse(payload)
backup=root/'deploy/backups'/('new-car-style-names-'+datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S%fZ'))
backup.mkdir(parents=True,exist_ok=False)
shutil.copy2(target,backup/target.name)
assert target.read_bytes()==(backup/target.name).read_bytes()
target.write_bytes(payload)
print('source_sha256='+hashlib.sha256(payload).hexdigest())
print('backup='+str(backup))
PY
cd "$task_root/deploy"
rollback_tag="market-new-car-names-rollback:$(date -u +%Y%m%dT%H%M%SZ)"
old_image=$(docker inspect --format '{{.Image}}' deploy-new-car-mcp-1)
docker image tag "$old_image" "$rollback_tag"
printf 'rollback_image=%s\n' "$rollback_tag"
BUILDKIT_PROGRESS=plain docker compose build new-car-mcp
docker compose up -d --no-deps new-car-mcp
docker compose ps new-car-mcp
docker compose logs --tail=10 new-car-mcp

